/**
 * Contract Tests for WebSocket Messages
 *
 * These tests ensure that messages generated by our frontend
 * match the expected format that the backend can deserialize.
 *
 * The contracts are auto-generated by the Rust backend during build.
 */

import {
  createAddUserMessage,
  createUpdateUserNameMessage,
  createUpdateUserColorMessage,
  createDeleteUser,
  createNewNote,
  createUpdateNote,
  createUpdateNoteText,
  createUpdateNoteTag,
  createUpdateNoteReorderBefore,
  createUpdateNoteReorderLast,
  createDeleteNote,
  createDeleteNoteUserBulk,
  createDeleteNoteBulk,
  createSplitNote,
} from '@/app/api/websocket'

// Import generated contracts
import wsActionsContract from '../../contracts/ws_actions.json'

describe('WebSocket Message Contract Tests', () => {
  describe('User Messages', () => {
    test('createAddUserMessage matches AddUser contract', () => {
      const message = createAddUserMessage('John Doe', '#FF5733')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.AddUser

      expect(parsed).toMatchObject({
        type: contract.type,
        name: expect.any(String),
        color: expect.any(String),
      })
      expect(parsed.type).toBe('AddUser')
    })

    test('createUpdateUserNameMessage matches UpdateUserName contract', () => {
      const message = createUpdateUserNameMessage(1, 'Jane Doe')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.UpdateUserName

      expect(parsed).toMatchObject({
        type: contract.type,
        id: expect.any(Number),
        name: expect.any(String),
      })
      expect(parsed.type).toBe('UpdateUserName')
    })

    test('createUpdateUserColorMessage matches UpdateUserColor contract', () => {
      const message = createUpdateUserColorMessage(1, '#33FF57')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.UpdateUserColor

      expect(parsed).toMatchObject({
        type: contract.type,
        id: expect.any(Number),
        color: expect.any(String),
      })
      expect(parsed.type).toBe('UpdateUserColor')
    })

    test('createDeleteUser matches RemoveUser contract', () => {
      const message = createDeleteUser(1)
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.RemoveUser

      expect(parsed).toMatchObject({
        type: contract.type,
        id: expect.any(Number),
      })
      expect(parsed.type).toBe('RemoveUser')
    })
  })

  describe('Note Messages', () => {
    test('createNewNote matches AddNote contract', () => {
      const message = createNewNote('1', 'Test note', 'todo')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.AddNote

      expect(parsed).toMatchObject({
        type: contract.type,
        owner: expect.any(Number),
        state: expect.any(String),
        text: expect.any(String),
      })
      expect(parsed.type).toBe('AddNote')
    })

    test('createUpdateNoteText matches UpdateNoteText contract', () => {
      const message = createUpdateNoteText('1', 'Updated text')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.UpdateNoteText

      expect(parsed).toMatchObject({
        type: contract.type,
        id: expect.any(Number),
        text: expect.any(String),
      })
      expect(parsed.type).toBe('UpdateNoteText')
    })

    test('createUpdateNoteTag with tag matches UpdateNoteTag contract', () => {
      const message = createUpdateNoteTag('1', 'Important')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.UpdateNoteTag

      expect(parsed).toMatchObject({
        type: contract.type,
        id: expect.any(Number),
        tag: expect.any(String),
      })
      expect(parsed.type).toBe('UpdateNoteTag')
    })

    test('createUpdateNoteTag with null matches UpdateNoteTag_none contract', () => {
      const message = createUpdateNoteTag('1', null)
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.UpdateNoteTag_none

      expect(parsed).toMatchObject({
        type: contract.type,
        id: expect.any(Number),
        tag: null,
      })
      expect(parsed.type).toBe('UpdateNoteTag')
    })

    test('createDeleteNote matches RemoveNote contract', () => {
      const message = createDeleteNote('1')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.RemoveNote

      expect(parsed).toMatchObject({
        type: contract.type,
        id: expect.any(Number),
      })
      expect(parsed.type).toBe('RemoveNote')
    })
  })

  describe('Reorder Messages', () => {
    test('createUpdateNoteReorderBefore matches Reorder contract', () => {
      const message = createUpdateNoteReorderBefore('1', 2)
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.Reorder

      expect(parsed).toMatchObject({
        type: contract.type,
        moved_item_id: expect.any(Number),
        over_id: {
          type: 'Before',
          id: expect.any(Number),
        },
      })
      expect(parsed.type).toBe('Reorder')
    })

    test('createUpdateNoteReorderLast matches Reorder_last contract', () => {
      const message = createUpdateNoteReorderLast('1', 'done')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.Reorder_last

      expect(parsed).toMatchObject({
        type: contract.type,
        moved_item_id: expect.any(Number),
        over_id: {
          type: 'Last',
          state: expect.any(String),
        },
      })
      expect(parsed.type).toBe('Reorder')
    })
  })

  describe('Bulk Operations', () => {
    test('createDeleteNoteUserBulk matches DeleteNotes contract', () => {
      const message = createDeleteNoteUserBulk('done', 1)
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.DeleteNotes

      expect(parsed).toMatchObject({
        type: contract.type,
        owner: expect.any(Number),
        status: expect.any(String),
      })
      expect(parsed.type).toBe('DeleteNotes')
    })

    test('createDeleteNoteBulk matches DeleteNotes_all contract', () => {
      const message = createDeleteNoteBulk('done')
      const parsed = JSON.parse(message)

      expect(parsed).toMatchObject({
        type: 'DeleteNotes',
        status: expect.any(String),
      })
      expect(parsed.type).toBe('DeleteNotes')
      // Note: createDeleteNoteBulk doesn't set owner, so it should be undefined
      expect(parsed.owner).toBeUndefined()
    })
  })

  describe('Complex Messages', () => {
    test('createUpdateNote matches NoteUpdate contract', () => {
      const message = createUpdateNote('1', 'Updated text', 'in_progress')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.NoteUpdate

      expect(parsed).toMatchObject({
        type: contract.type,
        id: expect.any(Number),
        updates: expect.arrayContaining([
          {
            target: 'Text',
            text: expect.any(String),
          },
          {
            target: 'Order',
            over_id: {
              type: 'Last',
              state: expect.any(String),
            },
          },
        ]),
      })
      expect(parsed.type).toBe('NoteUpdate')
    })

    test('createSplitNote matches SplitNote contract', () => {
      const message = createSplitNote('1', 'First part', 'Second part', 'todo', '2')
      const parsed = JSON.parse(message)
      const contract = wsActionsContract.SplitNote

      expect(parsed).toMatchObject({
        type: contract.type,
        original_id: expect.any(Number),
        original_text: expect.any(String),
        new_text: expect.any(String),
        new_state: expect.any(String),
        new_owner: expect.any(Number),
      })
      expect(parsed.type).toBe('SplitNote')
    })
  })

  describe('Field Type Validation', () => {
    test('numeric fields are numbers, not strings', () => {
      const userMessage = createUpdateUserNameMessage(1, 'Test')
      const userParsed = JSON.parse(userMessage)
      expect(typeof userParsed.id).toBe('number')

      const noteMessage = createUpdateNoteText('5', 'Test')
      const noteParsed = JSON.parse(noteMessage)
      expect(typeof noteParsed.id).toBe('number')
    })

    test('string fields are strings', () => {
      const message = createNewNote('1', 'Test note', 'todo')
      const parsed = JSON.parse(message)
      expect(typeof parsed.text).toBe('string')
      expect(typeof parsed.state).toBe('string')
    })

    test('optional fields handle null correctly', () => {
      const message = createUpdateNoteTag('1', null)
      const parsed = JSON.parse(message)
      expect(parsed.tag).toBeNull()
    })
  })
})

describe('Contract Structure Validation', () => {
  test('all expected contract variants exist', () => {
    const expectedVariants = [
      'AddNote',
      'AddNote_minimal',
      'UpdateNoteText',
      'UpdateNoteTag',
      'UpdateNoteTag_none',
      'Reorder',
      'Reorder_last',
      'RemoveNote',
      'AddUser',
      'UpdateUserName',
      'UpdateUserColor',
      'RemoveUser',
      'DeleteNotes',
      'DeleteNotes_all',
      'NoteUpdate',
      'UserUpdate',
      'NotifySnapshot',
      'SplitNote',
    ]

    for (const variant of expectedVariants) {
      expect(wsActionsContract).toHaveProperty(variant)
      expect((wsActionsContract as any)[variant]).toHaveProperty('type')
    }
  })

  test('contract file is valid JSON', () => {
    expect(wsActionsContract).toBeDefined()
    expect(typeof wsActionsContract).toBe('object')
  })
})